INSERT INTO `ouskhodro_comments` VALUES (1,1,'یک نویسنده دیدگاه وردپرس','wapuu@wordpress.example','https://fa.wordpress.org/','','2026-11-02 15:22:44','2026-11-02 11:52:44','سلام، این یک دیدگاه است.\nبرای شروع مدیریت، ویرایش و پاک کردن دیدگاه‌ها، لطفا بخش دیدگاه‌ها در پیشخوان را ببینید.\nتصاویر نویسندگان دیدگاه از <a href=\"https://gravatar.com/\">Gravatar</a> گرفته می‌شود.',0,'1','','comment',0,0);
