CREATE TABLE `ouskhodro_lkp_vehicles` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `source` varchar(32) COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT 'cafekhodro',
  `source_vehicle_id` varchar(64) COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `post_id` bigint unsigned DEFAULT NULL,
  `name` varchar(191) COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `name_normalized` varchar(191) COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `brand` varchar(100) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `source_group` varchar(100) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `production_stopped` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `source_vehicle` (`source`,`source_vehicle_id`),
  KEY `name_normalized` (`name_normalized`),
  KEY `brand` (`brand`),
  KEY `post_id` (`post_id`)
) ENGINE=InnoDB AUTO_INCREMENT=117 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;
